#!/usr/bin/env bash
# منبع واحد حقیقت (single source of truth) برای فایل‌های حیاتیِ امنیتی در
# دیپلوی — این فایل توسط چند مرحله در **هر دو** ورک‌فلوی
# deploy-staging.yml و deploy.yml (Production) source می‌شود تا لیست
# فقط یک‌ بار تعریف شود و هرگز در دو محیط از هم واگرا نشود:
#
#   - مسیرهای این آرایه از mirror اصلی lftp حذف (exclude) می‌شوند — یعنی
#     هرگز مشمول هیوریستیک skip بر پایه اندازه/زمان lftp نمی‌شوند.
#   - همین مسیرها بلافاصله بعد از mirror با `put` صریح (نه mirror) و به‌صورت
#     اجباری آپلود می‌شوند — `put` هیچ منطق skip ندارد، همیشه ارسال می‌کند.
#   - همین مسیرها بعد از آپلود با hash SHA256 در برابر آرتیفکت CI و در برابر
#     محتوای واقعی سرور راستی‌آزمایی می‌شوند.
#
# نکته مهم دربارهٔ اشتراک بین دو محیط: این آرایه فقط **مسیرهای نسبی به
# ریشهٔ بسته** (staging-build/ یا production-build/) را نگه می‌دارد، نه
# مسیر مطلق روی سرور. مسیر مطلق مقصد (public_html/ برای Production در
# برابر public_html/staging.veloratrade.ir/ برای staging) هرگز اینجا
# نوشته نمی‌شود و همیشه در همان ورک‌فلویی می‌ماند که مصرفش می‌کند —
# دقیقاً به همین دلیل این فایل بین دو محیط قابل اشتراک است بدون این‌که
# قانون غیرقابل‌مذاکرهٔ C-2 (مقصد Production هرگز پارامتری نشود) نقض شود.
#
# افزودن فایل حیاتی جدید در آینده فقط به یک تغییر در همین آرایه نیاز دارد؛
# هیچ مرحله‌ای در هیچ‌کدام از دو ورک‌فلو نباید این لیست را به‌صورت
# جداگانه hardcode کند.
CRITICAL_DEPLOY_FILES=(
  "localized/.csp-release.json"
  "public/locales/csp-manifest.json"
)
